"""Guards against the classic mistake: changing a model but forgetting the migration."""

from sqlalchemy import create_engine, text

from alembic import command
from tests.conftest import SYNC_TEST_URL, alembic_config


def test_models_match_migrations() -> None:
    # Raises AutogenerateDiffsDetected if models and the migrated schema differ.
    command.check(alembic_config())


def test_migrations_downgrade_and_upgrade_cleanly() -> None:
    cfg = alembic_config()
    command.downgrade(cfg, "base")
    command.upgrade(cfg, "head")


def test_api_key_hash_migration_backfills_existing_merchants() -> None:
    """Pre-Phase-1 merchant rows must get unique 64-char hashes during upgrade."""
    cfg = alembic_config()
    command.downgrade(cfg, "e5b21df584f3")

    sync_engine = create_engine(SYNC_TEST_URL)
    try:
        with sync_engine.begin() as conn:
            conn.execute(
                text(
                    "INSERT INTO merchants (name, email, phone_number) VALUES "
                    "('Legacy One', 'l1@example.com', '254711111111'), "
                    "('Legacy Two', 'l2@example.com', '254722222222')"
                )
            )
        command.upgrade(cfg, "head")
        with sync_engine.connect() as conn:
            hashes = list(conn.execute(text("SELECT api_key_hash FROM merchants")).scalars())
    finally:
        sync_engine.dispose()

    assert len(hashes) == 2
    assert all(isinstance(h, str) and len(h) == 64 for h in hashes)
    assert len(set(hashes)) == 2
